import{_ as i,o as r,c as n,ah as t}from"./chunks/framework.DDXs_i7t.js";const c=JSON.parse(`{"title":"10. März: Schmid belastet Wöginger – Die „Harte Prosa“ zerfällt","description":"Thomas Schmid, der Kronzeuge, sagt gegen August Wöginger aus. Ein dramatischer Wendepunkt für unsere Mockumentary und das 'Horten-Mysterium'.","frontmatter":{"title":"10. März: Schmid belastet Wöginger – Die „Harte Prosa“ zerfällt","description":"Thomas Schmid, der Kronzeuge, sagt gegen August Wöginger aus. Ein dramatischer Wendepunkt für unsere Mockumentary und das 'Horten-Mysterium'.","date":"2026-03-10T00:00:00.000Z"},"headers":[],"relativePath":"logbuch/2026-03-10-schmid-belastet-woeginger.md","filePath":"logbuch/2026-03-10-schmid-belastet-woeginger.md"}`),s={name:"logbuch/2026-03-10-schmid-belastet-woeginger.md"};function a(l,e,g,d,h,o){return r(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="⚖️-10-marz-schmid-belastet-woginger-–-die-„harte-prosa-zerfallt" tabindex="-1">⚖️ 10. März: Schmid belastet Wöginger – Die „Harte Prosa“ zerfällt <a class="header-anchor" href="#⚖️-10-marz-schmid-belastet-woginger-–-die-„harte-prosa-zerfallt" aria-label="Permalink to &quot;⚖️ 10. März: Schmid belastet Wöginger – Die „Harte Prosa“ zerfällt&quot;">​</a></h1><p>Es ist <strong>Dienstag, 14:49 Uhr</strong>. Während die Sonne über Linz steht, ziehen im Landesgericht dunkle Wolken über der Verteidigungsstrategie von August Wöginger auf. Der heutige Tag markiert den vielleicht wichtigsten Wendepunkt in <strong>Teil 4: Die politische Liebesgeschichte</strong>.</p><h3 id="der-kronzeuge-bricht-das-schweigen" tabindex="-1"><strong>Der Kronzeuge bricht das Schweigen</strong> <a class="header-anchor" href="#der-kronzeuge-bricht-das-schweigen" aria-label="Permalink to &quot;**Der Kronzeuge bricht das Schweigen**&quot;">​</a></h3><p><strong>Thomas Schmid</strong>, der ehemalige „Schattenkanzler“ des Finanzministeriums, hat heute in seiner Einvernahme die Karten auf den Tisch gelegt. Seine Aussagen sind pures Dynamit für das Narrativ des „Bürgeranliegens“:</p><ul><li><strong>Der explizite Wunsch:</strong> Schmid gab an, dass Wöginger ihn persönlich und direkt gebeten habe, für den ÖVP-Bürgermeister Michael L. zu intervenieren.</li><li><strong>Keine fachliche Prüfung:</strong> Die Qualifikation sei „nie ein Thema“ gewesen. Es ging einzig und allein darum, „Wögingers Wunsch zu entsprechen“.</li><li><strong>Die Chats der Macht:</strong> „Wir haben es geschafft 😃) Der Bürgermeister schuldet dir was!“ – Diese Nachricht von Schmid an Wöginger hallt heute wie ein Echo durch den Gerichtssaal.</li></ul><h3 id="analyse-der-pointillismus-der-gefalligkeiten" tabindex="-1"><strong>Analyse: Der Pointillismus der Gefälligkeiten</strong> <a class="header-anchor" href="#analyse-der-pointillismus-der-gefalligkeiten" aria-label="Permalink to &quot;**Analyse: Der Pointillismus der Gefälligkeiten**&quot;">​</a></h3><p>Für unsere Mockumentary ist dies die Bestätigung des <strong>„Pointillismus des Geldes“</strong>. Jeder Chat, jede SMS ist ein kleiner Punkt, der für sich genommen harmlos wirken mag („Bürgeranliegen“), aber im Gesamtbild ein monumentales Gemälde des Postenschachers ergibt.</p><blockquote><p><em>„Es ist wie ein Mosaik der Macht. Man muss weit genug zurücktreten, um den Abgrund zu sehen.“</em> — Oliver Masucci (als Thomas Schmid), Entwurf für Szene 88.</p></blockquote><h3 id="wogingers-verteidigung-in-bedrangnis" tabindex="-1"><strong>Wögingers Verteidigung in Bedrängnis</strong> <a class="header-anchor" href="#wogingers-verteidigung-in-bedrangnis" aria-label="Permalink to &quot;**Wögingers Verteidigung in Bedrängnis**&quot;">​</a></h3><p>Wöginger bleibt bei seiner Linie: Er habe nichts Unrechtes getan, es sei alles nur „Regionalpolitik“. Doch die kühle Präzision von Schmid setzt die „Harte Prosa“ der ÖVP massiv unter Druck. Die Entschuldigung Wögingers, dass es ihm „leid tue, was seine Bitte ausgelöst habe“, wirkt in diesem Kontext wie ein schwacher Schutzwall gegen die Flut der Beweise.</p><h3 id="was-das-fur-den-film-bedeutet" tabindex="-1"><strong>Was das für den Film bedeutet:</strong> <a class="header-anchor" href="#was-das-fur-den-film-bedeutet" aria-label="Permalink to &quot;**Was das für den Film bedeutet:**&quot;">​</a></h3><p>Wir haben heute exklusives Material für die finale Montage von Teil 4 gesammelt. Die Gegenüberstellung von Wögingers „Bürgeranliegen“-Rhetorik und Schmids „Wunsch-Erfüllung“-Aussage wird das emotionale Zentrum des Finales bilden.</p><ul><li><strong>Diebstahl der Zeit:</strong> Wir inszenieren diesen Prozess als den Moment, in dem die Zeit für das alte System abläuft.</li><li><strong>Der 21. April:</strong> Das Datum des Urteils ist nun unser Fixpunkt. Bis dahin werden wir die „Harte Prosa“ weiter dekonstruieren.</li></ul><h3 id="🛑-update-der-fahrplan-zum-urteil" tabindex="-1">🛑 UPDATE: Der Fahrplan zum Urteil <a class="header-anchor" href="#🛑-update-der-fahrplan-zum-urteil" aria-label="Permalink to &quot;🛑 UPDATE: Der Fahrplan zum Urteil&quot;">​</a></h3><ul><li><strong>Urteilsverkündung:</strong> Erwartet für den <strong>21. April 2026</strong>.</li><li><strong>Nächste Schritte:</strong> Wir bereiten eine Sonderfolge unseres Logbuch-Podcasts vor, in der wir die Aussagen von Schmid und Scharf gegenüberstellen.</li></ul><hr><p><strong>„Ein Finanzamt ist kein Taschenrechner? Vielleicht. Aber Gerechtigkeit ist eine exakte Wissenschaft.“</strong></p><p>👉 <a href="/recherche/thomas-schmid-chats-details.html">Die Schmid-Chats im Detail analysieren</a> 👉 <a href="/logbuch/2026-03-01-system-schluckauf-und-verschleierung.html">Zum aktuellen Stand der &#39;Marktbereinigung&#39;</a></p><hr><p><em>Berichterstattung vom 10. März 2026, 14:49 Uhr. Die Mockumentary schreibt sich fast von selbst.</em></p>',20)])])}const m=i(s,[["render",a]]);export{c as __pageData,m as default};
